// Removes the INTERNET permission from release builds only. The app never uses
// the network, but React Native and Expo's template declare INTERNET, and dev
// builds need it to load JavaScript from Metro. Gradle merges the release
// source set's manifest over src/main, so this leaves debug builds alone.
const fs = require('fs');
const path = require('path');
const { withDangerousMod } = require('expo/config-plugins');

const MANIFEST = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by plugins/with-release-no-internet.js. Don't edit by hand. -->
<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:tools="http://schemas.android.com/tools">
  <uses-permission android:name="android.permission.INTERNET" tools:node="remove" />
</manifest>
`;

module.exports = function withReleaseNoInternet(config) {
  return withDangerousMod(config, [
    'android',
    async (config) => {
      const dir = path.join(config.modRequest.platformProjectRoot, 'app', 'src', 'release');
      fs.mkdirSync(dir, { recursive: true });
      fs.writeFileSync(path.join(dir, 'AndroidManifest.xml'), MANIFEST);
      return config;
    },
  ]);
};
